package dev.koikaster.mite.compat.jei;
import dev.koikaster.mite.*;import java.util.*;import net.minecraft.world.item.*;import net.minecraft.world.item.alchemy.*;import net.minecraft.world.inventory.*;import net.minecraft.network.chat.Component;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.resources.ResourceLocation;import net.minecraftforge.common.brewing.BrewingRecipeRegistry;import net.minecraftforge.registries.ForgeRegistries;import mezz.jei.api.recipe.*;import mezz.jei.api.recipe.category.IRecipeCategory;import mezz.jei.api.recipe.transfer.IRecipeTransferInfo;import mezz.jei.api.gui.builder.IRecipeLayoutBuilder;import mezz.jei.api.gui.drawable.*;import mezz.jei.api.gui.ingredient.IRecipeSlotsView;import mezz.jei.api.helpers.*;import mezz.jei.api.gui.ITickTimer;import mezz.jei.api.recipe.transfer.*;import net.minecraft.world.entity.player.Player;import net.minecraft.network.chat.Component;
/** Enumerate actual Forge resolver results, not a parallel display recipe table. */
public final class JeiBrewing1420{
 public record View(ItemStack input,ItemStack ingredient,ItemStack output){}
 public static final RecipeType<View> TYPE=RecipeType.create(MiteReforged.ID,"brewing",View.class);
 public static List<View> views=List.of();
 private static String key(ItemStack stack){return ForgeRegistries.ITEMS.getKey(stack.getItem())+":"+(SourcePotionJei1420.uid(stack)!=null?SourcePotionJei1420.uid(stack):stack.save(new net.minecraft.nbt.CompoundTag()).toString());}
 private static List<ItemStack> nativeBottles(){var out=new ArrayList<ItemStack>();for(var potion:ForgeRegistries.POTIONS.getValues())for(Item form:List.of(Items.POTION,Items.SPLASH_POTION,Items.LINGERING_POTION))out.add(PotionUtils.setPotion(new ItemStack(form),potion));return out;}
 public static List<ItemStack> variants(){var known=new HashSet<String>();for(var stack:nativeBottles())known.add(key(stack));var found=new TreeSet<Integer>();found.add(0);var pending=new ArrayDeque<Integer>();pending.add(0);var out=new ArrayList<ItemStack>();var ingredients=new TreeSet<>(OriginalPotionRules1403.ingredients().keySet());while(!pending.isEmpty()){int before=pending.remove();var stack=SourceLegacyPotions1406.stack(before);if(known.add(key(stack)))out.add(stack);for(String item:ingredients){int next=OriginalPotionRules1403.mixedSubtype(before,item);if(OriginalPotionRules1403.canBrew(before,next)&&found.add(next))pending.add(next);}}return List.copyOf(out);}
 public static List<View> collect(){var bottles=new LinkedHashMap<String,ItemStack>();for(var stack:nativeBottles())bottles.putIfAbsent(key(stack),stack);for(var stack:variants())bottles.putIfAbsent(key(stack),stack);var ingredients=ForgeRegistries.ITEMS.getValues().stream().filter(i->i!=Items.AIR).map(ItemStack::new).filter(s->!JeiHeatRecipes.hidden(s)&&BrewingRecipeRegistry.isValidIngredient(s)).sorted(Comparator.comparing(s->ForgeRegistries.ITEMS.getKey(s.getItem()).toString())).toList();var out=new ArrayList<View>();var keys=new HashSet<String>();for(var input:bottles.values())for(var ingredient:ingredients){var result=BrewingRecipeRegistry.getOutput(input.copy(),ingredient.copy());if(result.isEmpty()||JeiHeatRecipes.hidden(result)||ItemStack.isSameItemSameTags(input,result))continue;if(keys.add(key(input)+"/"+key(ingredient)+"/"+key(result)))out.add(new View(input.copyWithCount(1),ingredient.copyWithCount(1),result.copyWithCount(1)));}views=List.copyOf(out);return views;}
 public static boolean matchesPotion(ItemStack wanted,ItemStack held){if(!wanted.is(held.getItem()))return false;String a=SourcePotionJei1420.uid(wanted),b=SourcePotionJei1420.uid(held);return a!=null||b!=null?Objects.equals(a,b):PotionUtils.getPotion(wanted)==PotionUtils.getPotion(held);}
 public static final class Transfer implements IRecipeTransferHandler<SourceBrewingMenu1412,View>{
  private final IRecipeTransferHandlerHelper errors;public Transfer(IRecipeTransferHandlerHelper errors){this.errors=errors;}
  public Class<? extends SourceBrewingMenu1412> getContainerClass(){return SourceBrewingMenu1412.class;}public Optional<MenuType<SourceBrewingMenu1412>> getMenuType(){return Optional.of(Content.BREW_MENU.get());}public RecipeType<View> getRecipeType(){return TYPE;}
  public IRecipeTransferError transferRecipe(SourceBrewingMenu1412 menu,View recipe,IRecipeSlotsView view,Player player,boolean maximum,boolean transfer){
   int available=0,ingredients=0,present=0;for(int i=4;i<40;i++){var stack=menu.getSlot(i).getItem();if(matchesPotion(recipe.input(),stack))available+=stack.getCount();if(stack.is(recipe.ingredient().getItem()))ingredients+=stack.getCount();}
   var needs=new ArrayList<JeiNativeTransfer.Need>();var inputs=new ArrayList<Integer>();for(int i=0;i<3;i++){var slot=menu.getSlot(i);if(slot.hasItem()){if(matchesPotion(recipe.input(),slot.getItem()))present++;}else if(available>0){needs.add(new JeiNativeTransfer.Need(i,List.of(recipe.input()),1));inputs.add(i);available--;present++;}}
   if(present==0)return errors.createUserErrorWithTooltip(Component.translatable("jei.mite_reforged.missing"));var ingredient=menu.getSlot(3).getItem();if(!ingredient.isEmpty()&&!ingredient.is(recipe.ingredient().getItem()))return errors.createUserErrorWithTooltip(Component.translatable("jei.mite_reforged.clear_grid"));
   int wanted=ingredient.isEmpty()?(maximum?Math.min(ingredients,menu.getSlot(3).getMaxStackSize(recipe.ingredient())):1):0;if(ingredient.isEmpty()){if(wanted<=0)return errors.createUserErrorWithTooltip(Component.translatable("jei.mite_reforged.missing"));inputs.add(3);}
   IRecipeTransferError last=null;for(int amount=wanted;amount>=Math.min(1,wanted);amount--){var attempt=new ArrayList<>(needs);if(amount>0)attempt.add(new JeiNativeTransfer.Need(3,List.of(recipe.ingredient()),amount));last=JeiNativeTransfer.fill(menu,attempt,4,36,inputs,false,false,errors);if(last==null)return transfer?JeiNativeTransfer.fill(menu,attempt,4,36,inputs,false,true,errors):null;}return last;
  }
 }
 public static final class Category implements IRecipeCategory<View>{
  private static final ResourceLocation TEXTURE=Content.id("textures/gui/container/source_brewing_stand1412.png");private final IDrawable background,icon;private final IDrawableAnimated arrow;private final ITickTimer bubbles;
  public Category(IGuiHelper gui){background=gui.createDrawable(TEXTURE,54,14,64,60);icon=gui.createDrawableItemStack(new ItemStack(Items.BREWING_STAND));arrow=gui.createAnimatedDrawable(gui.createDrawable(TEXTURE,176,0,9,28),400,IDrawableAnimated.StartDirection.TOP,false);bubbles=gui.createTickTimer(14,6,false);}
  public RecipeType<View> getRecipeType(){return TYPE;}public Component getTitle(){return Component.translatable("container.brewing");}public IDrawable getIcon(){return icon;}public int getWidth(){return 116;}public int getHeight(){return 62;}
  public void setRecipe(IRecipeLayoutBuilder builder,View view,IFocusGroup focus){builder.addSlot(RecipeIngredientRole.INPUT,2,32).addItemStack(view.input());builder.addSlot(RecipeIngredientRole.INPUT,25,39).addItemStack(view.input());builder.addSlot(RecipeIngredientRole.INPUT,48,32).addItemStack(view.input());builder.addSlot(RecipeIngredientRole.INPUT,25,3).addItemStack(view.ingredient());builder.addSlot(RecipeIngredientRole.OUTPUT,92,3).addItemStack(view.output()).setStandardSlotBackground();}
  public void draw(View view,IRecipeSlotsView slots,GuiGraphics graphics,double mouseX,double mouseY){background.draw(graphics,0,0);arrow.draw(graphics,43,2);int height=new int[]{29,24,20,16,11,6,0}[bubbles.getValue()];if(height>0)graphics.blit(TEXTURE,11,29-height,185,29-height,12,height);}
 }
 private JeiBrewing1420(){}
}
